        p += off;
        left -= off;

        rc = MP3Decode(m->dec, &p, &left, m->pcm, 0);

        if (rc == ERR_MP3_INDATA_UNDERFLOW) {
            if (off > 0) {
                m->in_len -= (size_t)off;
                memmove(m->in, m->in + off, m->in_len);
            }

            return delivered;
        }

        if (rc != ERR_MP3_NONE && rc != ERR_MP3_MAINDATA_UNDERFLOW) {
            size_t skip = (size_t)off + 1;

            m->resyncs++;
            m->in_len -= skip;
            memmove(m->in, m->in + skip, m->in_len);
            continue;
