static void tcp_timer_expiry(FAR void *arg)
{
  FAR struct tcp_conn_s *conn = NULL;
  tcp_conn_list_lock();
  while ((conn = tcp_nextconn(conn)) != NULL)
    {
      if (conn == arg)
        {
          FAR struct net_driver_s *dev = conn->dev;
          conn->timeout = true;
          tcp_conn_list_unlock();
          netdev_lock(dev);
          netdev_txnotify_dev(dev, TCP_POLL);
          netdev_unlock(dev);
          return;
        }
    }
  tcp_conn_list_unlock();
}
