def read_for(fd, idle_ms, timeout_s, min_s=0.0):
    """Collect output until it goes quiet.

    min_s exists because the benchmark modes are deliberately silent while
    they run and print only once at the end: without a floor, the silence of
    a ten-second transfer looks exactly like the silence after a reply and
    the reader would stop before the answer arrived.
    """
    chunks = []
    started = time.monotonic()
    last = started
    while True:
        now = time.monotonic()
        if now - started > timeout_s:
            break
        try:
            data = os.read(fd, 4096)
        except BlockingIOError:
            data = b""
        except OSError:
            break
        if data:
            chunks.append(data)
            last = time.monotonic()
        else:
            if (time.monotonic() - started > min_s and
                    time.monotonic() - last > idle_ms / 1000.0):
                break
            time.sleep(0.02)
    return b"".join(chunks)

